import { createHash } from "crypto";
import { OrderEventKind } from "../domain/order";

const KIND_CODE: Record<OrderEventKind, string> = {
  PAID: "paid",
  SHIPPED: "ship",
  DELIVERED: "dlvd",
};

/**
 * 알림 메시지 키 — 사내 키 규약 `<네임스페이스>.<이벤트>.<업무 식별자>`.
 * 소비 측은 이 키로 이미 처리한 메시지를 걸러낸다(재전달 대비).
 *
 * mqpub 3.x는 한 배치 안에서 키의 앞 16바이트가 같으면 첫 메시지만 저장한다.
 * 공통 접두(네임스페이스·이벤트명) 때문에 서로 다른 주문이 같은 앞부분을 갖게 되므로,
 * 키 맨 앞에 논리 키의 결정적 해시(hex 16자)를 둬서 앞 16바이트만으로 구별되게 한다.
 */
export function messageKey(namespace: string, kind: OrderEventKind, orderNo: string): string {
  const logical = `${namespace}.${KIND_CODE[kind]}.${orderNo}`;
  const digest = createHash("sha256").update(logical).digest("hex").slice(0, 16);
  return `${digest}.${logical}`;
}

